def longest_increasing_subsequence(nums: list) -> int:
    """
    Returns the length of the longest strictly increasing subsequence in nums
    using dynamic programming (O(n^2) time, O(n) space).
    """
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # dp[i] is length of LIS ending at i

    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def is_valid_parentheses(s):
    """
    Return True if the string s contains valid parentheses.
    Valid pairs are: (), [], {}. Any other character will make the string invalid.
    """
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    opens = set(pairs.values())

    for ch in s:
        if ch in opens:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            # treat any non-bracket character as invalid
            return False

    return not stack

