def longest_increasing_subsequence(nums):
    """
    Return the length of the longest strictly increasing subsequence in nums using dynamic programming.
    """
    if not nums:
        return 0

    n = len(nums)
    # dp[i] will hold the length of the longest increasing subsequence ending at i
    dp = [1] * n

    max_len = 1  # at least one element exists

    for i in range(n):
        # consider all previous elements
        for j in range(i):
            if nums[j] < nums[i]:
                # if we can extend the subsequence ending at j with nums[i]
                candidate = dp[j] + 1
                if candidate > dp[i]:
                    dp[i] = candidate
        if dp[i] > max_len:
            max_len = dp[i]

    return max_len

