def binary_search(arr, target):
    """
    Return the index of target in sorted array arr, or -1 if not found.
    Assumes arr is sorted in non-decreasing order.
    """
    if not arr:
        return -1  # empty array edge case

    left = 0
    right = len(arr) - 1

    while left <= right:
        mid = left + (right - left) // 2
        mid_val = arr[mid]
        if mid_val == target:
            return mid
        elif target < mid_val:
            right = mid - 1
        else:
            left = mid + 1

    return -1  # not found

